/**
 * @file labs/mean-square-boundary/step-eigenbasis-lyapunov-g1.gen.ts
 * @description Generated by `scripts/generate-lyapunov-step-kernels.ts` (do not edit): one renormalised linearised
 * heavy-ball step for 1 step size sharing one scaled minibatch deviation, on the row-major pair layout
 * (`stepEigenbasisLyapunovG1`). Same operations per state as `stepEigenbasisLyapunovGeneral`; `x`, `xPrev`, `r` hold the
 * states one after the other (`n` entries each).
 * @cold
 */
import { fdlibmLog } from '../../src/math/index.ts';

export function stepEigenbasisLyapunovG1(
  sum: Float64Array,
  curvature: Float64Array,
  x: Float64Array,
  xPrev: Float64Array,
  r: Float64Array,
  n: number,
  beta: number,
  etas: Float64Array,
  logs: Float64Array,
  recordLog: boolean,
): void {
  const eta0 = etas[0]!;
  for (let a = 0; a < n; (a = (a + 1) | 0)) {
    const ca = curvature[a]!;
    r[a] = ca * x[a]!;
  }
  let p = 0;
  for (let a = 0; a < n; (a = (a + 1) | 0)) {
    const vd = sum[p]!;
    p = (p + 1) | 0;
    const xa0 = x[a]!;
    let ra0 = r[a]! + vd * xa0;
    for (let c = (a + 1) | 0; c < n; (c = (c + 1) | 0)) {
      const v = sum[p]!;
      p = (p + 1) | 0;
      ra0 += v * x[c]!;
      r[c] = r[c]! + v * xa0;
    }
    r[a] = ra0;
  }
  let nrm0 = 0.0;
  for (let k = 0; k < n; (k = (k + 1) | 0)) {
    const k0 = k;
    const cur0 = x[k0]!;
    const next0 = cur0 + beta * (cur0 - xPrev[k0]!) - eta0 * r[k0]!;
    xPrev[k0] = cur0;
    x[k0] = next0;
    nrm0 += next0 * next0 + cur0 * cur0;
  }
  const nu0 = Math.sqrt(nrm0);
  if (recordLog) {
    logs[0] = logs[0]! + fdlibmLog(nu0);
  }
  const inv0 = 1.0 / nu0;
  for (let k = 0; k < n; (k = (k + 1) | 0)) {
    const k0 = k;
    x[k0] = x[k0]! * inv0;
    xPrev[k0] = xPrev[k0]! * inv0;
  }
}
